// Development-only extraction and indexing oracle from the pinned reference.
import {execFileSync} from 'node:child_process';
import {createRequire} from 'node:module';
import {readFileSync,writeFileSync,mkdirSync,mkdtempSync,rmSync} from 'node:fs';
import {dirname,join,resolve} from 'node:path';
import {tmpdir} from 'node:os';
import {fileURLToPath} from 'node:url';
const root=resolve(process.argv[2]),revision='6aa358ccbae30fbf27318f79ee183212f726f9ba';
if(execFileSync('git',['-C',root,'rev-parse','HEAD'],{encoding:'utf8'}).trim()!==revision)throw Error('Wrong reference revision');
const require=createRequire(join(root,'package.json')),ts=require('typescript');
const {codeigniterResolver:resolver}=require('./dist/resolution/frameworks/codeigniter.js');
const Project=Object.values(require('./dist/index.js')).find(value=>typeof value==='function'&&typeof value.init==='function'&&typeof value.open==='function');
const {ReferenceResolver}=require('./dist/resolution/index.js');
const strip=node=>{const copy={...node};delete copy.updatedAt;return copy;};
const cases=[],seen=new Set(),projects=[];
function add(path,source,origin){const key=JSON.stringify([path,source]);if(seen.has(key))return;seen.add(key);const extracted=resolver.extract(path,source);cases.push({path,source,origin,expected:{nodes:extracted.nodes.map(strip),references:extracted.references}});}
function literal(node,tree,depth=0){if(!node||depth>20)return undefined;if(ts.isStringLiteral(node)||ts.isNoSubstitutionTemplateLiteral(node))return node.text;if(ts.isNumericLiteral(node))return Number(node.text);if(node.kind===ts.SyntaxKind.TrueKeyword)return true;if(node.kind===ts.SyntaxKind.FalseKeyword)return false;if(ts.isArrayLiteralExpression(node)){const values=node.elements.map(value=>literal(value,tree,depth+1));return values.every(value=>value!==undefined)?values:undefined;}if(ts.isObjectLiteralExpression(node)){const object={};for(const property of node.properties){if(ts.isSpreadAssignment(property)){const spread=literal(property.expression,tree,depth+1);if(!spread)return undefined;Object.assign(object,spread);continue;}if(ts.isShorthandPropertyAssignment(property)){const value=literal(property.name,tree,depth+1);if(value===undefined)return undefined;object[property.name.text]=value;continue;}if(!ts.isPropertyAssignment(property))return undefined;const key=ts.isIdentifier(property.name)?property.name.text:literal(ts.isComputedPropertyName(property.name)?property.name.expression:property.name,tree,depth+1);const value=literal(property.initializer,tree,depth+1);if(key===undefined||value===undefined)return undefined;object[key]=value;}return object;}if(ts.isBinaryExpression(node)&&node.operatorToken.kind===ts.SyntaxKind.PlusToken){const left=literal(node.left,tree,depth+1),right=literal(node.right,tree,depth+1);if(typeof left==='string'&&typeof right==='string')return left+right;}if(ts.isIdentifier(node)){for(let block=node.parent;block;block=block.parent){for(const statement of block.statements??[]){if(statement.pos>node.pos)continue;if(ts.isVariableStatement(statement))for(const declaration of statement.declarationList.declarations)if(declaration.name.getText(tree)===node.text)return literal(declaration.initializer,tree,depth+1);}}}if(ts.isCallExpression(node)&&node.expression.getText(tree)==='JSON.stringify'){const value=literal(node.arguments[0],tree,depth+1);if(value!==undefined)return JSON.stringify(value);}}
const tree=ts.createSourceFile('source.ts',readFileSync(join(root,'__tests__/codeigniter.test.ts'),'utf8'),ts.ScriptTarget.Latest,true);const files={};
function visit(node){if(ts.isCallExpression(node)){const name=node.expression.getText(tree);if(['routeNames','extract'].includes(name)){const path=literal(node.arguments[0],tree),source=literal(node.arguments[1],tree);if(typeof path==='string'&&typeof source==='string')add(path,source,'original route extraction');}if(name==='write'){let group='';for(let parent=node.parent;parent;parent=parent.parent){if(ts.isCallExpression(parent)&&parent.expression.getText(tree)==='describe'){group=literal(parent.arguments[0],tree);break;}}if(group==='a CodeIgniter project, indexed'){const path=literal(node.arguments[0],tree),source=literal(node.arguments[1],tree);if(typeof path!=='string'||typeof source!=='string')throw Error('Missing original input');files[path]=source;}}}ts.forEachChild(node,visit);}visit(tree);
projects.push({name:'original-project',files});
projects.push({name:'module-isolation',files:{'application/config/routes.php':"<?php $route['default_controller']='home';\n",'application/modules/a/models/Item_model.php':'<?php class Item_model { public function find() {} }','application/modules/b/models/Item_model.php':'<?php class Item_model { public function find() {} }','application/modules/a/controllers/Home.php':'<?php\nclass Home {\n public function index() { $this->item_model->find(); }\n}\n','application/controllers/Home.php':'<?php\nclass Home {\n public function index() { $this->item_model->find(); }\n}\n'}});
projects.push({name:'library-aliases',files:{'application/config/routes.php':"<?php $route['default_controller']='home';\n",'application/controllers/Home.php':"<?php\nclass Home {\n public function index() { $this->load->library('tools/mailer', null, 'messages'); $this->messages->send(); }\n}\n",'application/libraries/Mailer.php':'<?php class Mailer { public function send() {} }'}});
projects.push({name:'inherited-model-and-controller',files:{
'application/config/routes.php':"<?php $route['default_controller']='home'; $route['all']='home/listing';\n",
'application/core/BaseController.php':"<?php class BaseController { public function listing() {} }",
'application/controllers/Home.php':"<?php\nclass Home extends BaseController {\n public function index() { $this->item_model->price(); $this->load->view('home'); }\n}\n",
'application/core/BaseModel.php':"<?php class BaseModel { public function price() {} }",
'application/models/Item_model.php':"<?php class Item_model extends BaseModel {}",
'application/views/home.php':"<?php echo 'home';"
}});
for(const path of ['application/config/routes.php','nested/application/config/dev/routes.php','application/modules/shop/config/routes.php','application/controllers/Blog.php','application/modules/blog/controllers/Blog.php','a.php'])for(const source of ["<?php\n/* 😀 */ $route['é/(:num)']['post']='blog/show/$1';\n", "<?php\nclass Blog {\n public function café() {}\n public function Index() {}\n public function & show() {}\n}","<?php\nclass Blog {\n protected function skip() {}\n public function _hide() {}\n function go() {}\n}"])add(path,source,'Unicode and applicability');
for(const project of projects){const dir=mkdtempSync(join(tmpdir(),'prometeu-ci-'));let indexed;try{
 for(const [path,source]of Object.entries(project.files)){mkdirSync(dirname(join(dir,path)),{recursive:true});writeFileSync(join(dir,path),source);add(path,source,project.name);}
 indexed=await Project.init(dir,{silent:true});const result=await indexed.indexAll();if(!result.success)throw Error('Index failed');
 const context=new ReferenceResolver(dir,indexed.queries);context.initialize();const nodes=indexed.queries.getAllNodes(),byId=new Map(nodes.map(node=>[node.id,node]));const edges=nodes.flatMap(node=>indexed.queries.getOutgoingEdges(node.id));
 project.nodes=nodes.map(strip);project.routes=nodes.filter(node=>node.kind==='route').map(node=>({node:strip(node),targets:indexed.queries.getOutgoingEdges(node.id).map(edge=>({kind:edge.kind,node:strip(indexed.getNode(edge.target)),metadata:edge.metadata}))}));
 project.edges=edges.filter(edge=>edge.metadata?.framework==='codeigniter');project.superclasses=Object.fromEntries(nodes.filter(node=>node.kind==='class').map(node=>[node.id,(context.context.getSupertypeNodes?.(node.id)??[]).map(node=>node.id)]));
 const pending=Object.keys(project.files).flatMap(path=>indexed.queries.getUnresolvedReferencesInFile(path,100000));const resolved=edges.filter(edge=>edge.metadata?.refName).map(edge=>({fromNodeId:edge.source,referenceName:edge.metadata.refName,referenceKind:edge.metadata.refKind??edge.kind,line:edge.line??byId.get(edge.source).startLine,column:edge.column??0,filePath:byId.get(edge.source).filePath,language:byId.get(edge.source).language}));
 const referenceKeys=new Set();project.resolutions=[];
 for(const reference of [...pending,...resolved]){const key=JSON.stringify([reference.fromNodeId,reference.referenceName,reference.referenceKind,reference.line,reference.column]);if(referenceKeys.has(key))continue;referenceKeys.add(key);const result=resolver.resolve(reference,context.context);project.resolutions.push({reference,expected:result?{id:result.targetNodeId,confidence:result.confidence}:null});}
 console.log(project.name,project.routes.length,project.resolutions.length,project.edges.length);
}finally{indexed?.close();rmSync(dir,{recursive:true,force:true});}}
const destination=dirname(fileURLToPath(import.meta.url));writeFileSync(join(destination,'cases.json'),JSON.stringify({revision,cases,projects},null,2)+'\n');writeFileSync(join(destination,'LICENSE'),readFileSync(join(root,'LICENSE')));console.log(cases.length,'extractions');
